head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > getAllBASE64Parameter]<br/>URL 쿼리 문자열(GET 방식)의 모든 파라미터를 Base64 디코딩하여 JSON 객체로 반환합니다.",
    "validation" : [
        "모든 파라미터의 키-값 쌍 객체를 반환해야 합니다.",
        "각 값은 Base64 디코딩된 상태이고, 파라미터명(키)은 디코딩하지 않고 원본 그대로 유지되어야 합니다.",
        "파라미터가 없으면 빈 객체({})를 반환해야 합니다.",
        "※ WebSquare.text.BASE64URLEncoder 로 인코딩한 값을 사용해야 합니다. 표준 btoa 와 인코딩 방식이 다릅니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getAllBASE64Parameter_onclick = function () {
    var result = $p.getAllBASE64Parameter();

    // w2xPath 제외
    var filtered = {};
    var keys = Object.keys(result);
    for (var i = 0; i < keys.length; i++) {
        if (keys[i] !== "w2xPath") {
            filtered[keys[i]] = result[keys[i]];
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getAllBASE64Parameter() (w2xPath 제외) : " + JSON.stringify(filtered));

    var filteredKeys = Object.keys(filtered);
    if (filteredKeys.length > 0) {
        for (var j = 0; j < filteredKeys.length; j++) {
            wf_body_bottom.getObj("scwin").setReturnValue("  " + filteredKeys[j] + " : " + filtered[filteredKeys[j]]);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("Base64 파라미터 없음 (빈 객체)");
    }
}



scwin.btn_navigateWithBase64_onclick = function () {
    // WebSquare.text.BASE64URLEncoder 로 인코딩
    var enc1 = WebSquare.text.BASE64URLEncoder("Hello");
    var enc2 = WebSquare.text.BASE64URLEncoder("World");

    wf_body_bottom.getObj("scwin").setReturnValue("$p.url 로 Base64 파라미터 전달하여 이동합니다.");
    wf_body_bottom.getObj("scwin").setReturnValue("key1=" + enc1 + " (Hello), key2=" + enc2 + " (World)");

    $p.url("/sample/$p/$p_M_getAllBASE64Parameter_1.xml", {
        spa: false,
        param: {"key1": enc1, "key2": enc2}
    });
}
